                d="M 200 -100 C 200 300 600 200 600 500 C 600 800 200 700 200 900 C 200 1100 1200 1100 1200 900 C 1200 700 800 600 800 400 C 800 200 1200 200 1200 -100"
                fill="none"
                stroke="#1a0505"
                strokeWidth="80"
                strokeLinecap="round"
              />
              {/* Road glow */}
              <path
                d="M 200 -100 C 200 300 600 200 600 500 C 600 800 200 700 200 900 C 200 1100 1200 1100 1200 900 C 1200 700 800 600 800 400 C 800 200 1200 200 1200 -100"
