                  absolute w-full max-w-xs sm:max-w-2xl md:max-w-5xl lg:max-w-6xl
                  px-3 sm:px-4 md:px-0
                  transition-all duration-700 ease-[cubic-bezier(0.19,1,0.22,1)]
