              >
                {/* Card shell */}
                <div className="pointer-events-auto bg-black/80 backdrop-blur-xl border border-red-900/40 p-[2px] sm:p-1 rounded-2xl shadow-[0_0_100px_-20px_rgba(220,38,38,0.3)] overflow-hidden relative group">
