                  {/* ✅ FIX 6: max-h is defined with svh to account for mobile bottom bars */}
                  <div className="flex flex-col md:flex-row max-h-[80svh] md:max-h-none overflow-y-auto hud-scroll bg-neutral-950/80 rounded-xl">

                    {/* Image */}
