          width:clamp(80px,25vw,240px); height:0;
          border-top:0.3vmin solid #C11B1F;
          box-shadow:0 0 1vmin rgba(193,27,31,0.85),0 0 0.4vmin rgba(193,27,31,0.85) inset;
