          ].map(([x1,y1,x2,y2,cx1,cy1,cx2,cy2],i) => (
            <path key={i}
              d={`M ${x1} ${y1} C ${cx1} ${cy1}, ${cx2} ${cy2}, ${x2} ${y2}`}
